admin_helper_source:
# Elevated helper: compact only the existing Docker data disk after a verified backup.
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$diskPath = 'C:\Users\ADMIN\AppData\Local\Docker\wsl\disk\docker_data.vhdx'
$readyPath = Join-Path $PSScriptRoot 'compact-vhdx-ready.json'
$statusPath = Join-Path $PSScriptRoot 'compact-vhdx-status.json'
$diskpartPath = Join-Path $PSScriptRoot 'compact-vhdx-diskpart.txt'
$logPath = Join-Path $PSScriptRoot 'compact-vhdx-diskpart.log'
function Save-Status($value) {
    $value | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $statusPath -Encoding utf8
}
try {
    $principal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'Windows Administrator permission is required.'
    }
    Save-Status ([ordered]@{state='waiting_for_verified_backup';administrator=$true;utc=[DateTime]::UtcNow.ToString('o')})
    $deadline = [DateTime]::UtcNow.AddMinutes(20)
    while (-not (Test-Path -LiteralPath $readyPath)) {
        if ([DateTime]::UtcNow -gt $deadline) { throw 'Timed out waiting for verified offline backup.' }
        Start-Sleep -Milliseconds 500
    }
    $ready = Get-Content -LiteralPath $readyPath -Raw | ConvertFrom-Json
    if ($ready.source_path -ne $diskPath -or -not $ready.backup_verified) { throw 'Invalid backup authorization record.' }
    if ($ready.source_sha256 -ne $ready.backup_sha256) { throw 'Backup checksum mismatch.' }
    $backupResolved = (Resolve-Path -LiteralPath $ready.backup_path).ProviderPath
    if (-not $backupResolved.StartsWith('D:\DBMS-VHDX-Backup-', [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Unexpected backup location.'
    }
    if ((Get-Item -LiteralPath $backupResolved).Length -ne $ready.source_bytes) { throw 'Backup length mismatch.' }
    if ((Resolve-Path -LiteralPath $diskPath).ProviderPath -ne $diskPath) { throw 'Unexpected Docker disk path.' }
    $before = (Get-Item -LiteralPath $diskPath).Length
    if ($before -ne $ready.source_bytes) { throw 'Docker disk changed after backup.' }
    $handle = [IO.File]::Open($diskPath,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
    $handle.Dispose()
    $freeBefore = (Get-PSDrive C).Free
    @("select vdisk file=`"$diskPath`"", 'compact vdisk', 'exit') | Set-Content -LiteralPath $diskpartPath -Encoding ascii
    Save-Status ([ordered]@{state='compacting';source_bytes_before=$before;utc=[DateTime]::UtcNow.ToString('o')})
    $output = & "$env:SystemRoot\System32\diskpart.exe" /s $diskpartPath 2>&1
    $diskpartExit = $LASTEXITCODE
    $output | Set-Content -LiteralPath $logPath -Encoding utf8
    $after = (Get-Item -LiteralPath $diskPath).Length
    if ($diskpartExit -ne 0 -or ($output -join "`n") -match '(?i)encountered an error|failed to|Virtual Disk Service error') {
        throw "DiskPart failed; inspect $logPath"
    }
    Save-Status ([ordered]@{state='compact_finished';diskpart_exit=$diskpartExit;source_bytes_before=$before;
        source_bytes_after=$after;windows_free_bytes_before=$freeBefore;windows_free_bytes_after=(Get-PSDrive C).Free;
        backup_path=$backupResolved;utc=[DateTime]::UtcNow.ToString('o')})
} catch {
    Save-Status ([ordered]@{state='failed';error=$_.Exception.Message;utc=[DateTime]::UtcNow.ToString('o')})
    exit 1
}
